                m_awaddr_reg  <= s_awaddr_reg;
                m_awprot_reg  <= s_awprot_reg;
                m_awvalid_reg <= 1'b1;
            end else if (m_aw_handshake) begin
                m_awvalid_reg <= 1'b0;
            end
            m_awready_reg <= s_awready_synced;
        end
    end

